async def act(page):
    """
    Attempt to create a Shipping report for the range 08/05/2022 -> 03/01/2023 from the current page state.

    Behavior:
    - Navigate (relative goto) to the Sales > Shipping report page.
    - If the admin Shipping report UI is present, fill the From/To inputs, click the report-generation button scoped
      to the form that contains the From field (preferred), wait for the report to generate, and attempt to export CSV
      as the final action.
    - If the Shipping report UI is not present (likely because we are on the storefront or not authenticated), navigate
      to the admin login page (/index.php/admin/) and return so the caller may authenticate.

    Note: Per instructions, do NOT change the "Your Language:" combobox. KB helpers are not called because they are
    dashboard-focused and do not implement the Sales > Shipping workflow.
    """
    # Target relative URLs
    shipping_report_path = '/index.php/admin/report/sales_shipping/shipping/'
    admin_login_path = '/index.php/admin/'

    # Step 1: Navigate to the Shipping report page
    await page.goto(shipping_report_path)
    await page.wait_for_load_state('domcontentloaded')
    await page.wait_for_timeout(600)  # small delay for dynamic UI

    # Robust helper to fill inputs by accessible label variants
    async def fill_by_label_variants(variants, value):
        for lbl in variants:
            try:
                loc = page.get_by_label(lbl)
                if await loc.count() > 0:
                    await loc.fill(value)
                    return True
            except Exception:
                # transient DOM issue or label not present -> try next
                continue
        return False

    FROM_DATE = "08/05/2022"
    TO_DATE = "03/01/2023"
    from_label_variants = ["From", "From:", "from", "Start Date", "Start"]
    to_label_variants = ["To", "To:", "to", "End Date", "End"]

    # Step 2: Detect whether we are on the admin Shipping report UI by checking for the date fields
    from_found = False
    to_found = False
    try:
        # Quick non-exceptional check for the most likely exact labels first
        loc_from = page.get_by_label("From")
        if await loc_from.count() > 0:
            from_found = True
        loc_to = page.get_by_label("To")
        if await loc_to.count() > 0:
            to_found = True
    except Exception:
        # ignore and rely on fallback detection
        pass

    # If the exact labels weren't found, attempt the variants to detect admin UI
    if not from_found:
        from_found = await fill_by_label_variants(from_label_variants, "")  # just detect presence
    if not to_found:
        to_found = await fill_by_label_variants(to_label_variants, "")

    # If we did not detect admin Shipping UI (no From/To), navigate to admin login and stop so user can authenticate
    if not (from_found or to_found):
        # We are likely on the storefront or have been redirected; go to admin login for authentication
        await page.goto(admin_login_path)
        await page.wait_for_load_state('domcontentloaded')
        # Do not attempt further actions because authentication is required to access the report.
        return

    # Step 3: Fill the From/To fields with the requested dates
    await fill_by_label_variants(from_label_variants, FROM_DATE)
    await fill_by_label_variants(to_label_variants, TO_DATE)

    # Allow datepickers to settle
    await page.wait_for_timeout(400)

    # Step 4: Click the report generation button scoped to the form containing the From input (preferred)
    clicked_generate = False
    candidate_button_names = ["Show Report", "Show", "Refresh", "Filter", "Submit", "Apply", "Go"]

    try:
        forms = page.get_by_role("form")
        if await forms.count() > 0:
            # Scope to a form that contains the 'From' control
            form_with_from = forms.filter(has=page.get_by_label("From"))
            if await form_with_from.count() == 0:
                form_with_from = forms.filter(has=page.get_by_label("from"))

            if await form_with_from.count() > 0:
                for name in candidate_button_names:
                    btn = form_with_from.get_by_role("button", name=name)
                    if await btn.count() > 0:
                        await btn.click()
                        clicked_generate = True
                        break
    except Exception:
        clicked_generate = False

    # Global fallback: try named buttons anywhere on the page
    if not clicked_generate:
        for name in candidate_button_names:
            try:
                btn = page.get_by_role("button", name=name)
                if await btn.count() > 0:
                    await btn.click()
                    clicked_generate = True
                    break
            except Exception:
                continue

    # Additional fallback: scan buttons for keywords
    if not clicked_generate:
        try:
            buttons = page.get_by_role("button")
            if await buttons.count() > 0:
                total = await buttons.count()
                for i in range(total):
                    b = buttons.nth(i)
                    try:
                        text = (await b.inner_text()).strip()
                    except Exception:
                        text = ""
                    if text and ("report" in text.lower() or "filter" in text.lower() or "show" in text.lower()):
                        await b.click()
                        clicked_generate = True
                        break
        except Exception:
            pass

    # Wait for report generation / UI update
    await page.wait_for_timeout(1200)

    # Step 5: Attempt to export CSV as the final action (may navigate / download)
    export_labels = ["Export to CSV", "Export CSV", "Export", "CSV", "Download CSV"]
    exported = False

    for lbl in export_labels:
        try:
            link = page.get_by_role("link", name=lbl)
            if await link.count() > 0:
                await link.click()
                exported = True
                break
        except Exception:
            pass
        try:
            btn = page.get_by_role("button", name=lbl)
            if await btn.count() > 0:
                await btn.click()
                exported = True
                break
        except Exception:
            pass

    # Conservative fallback: click first link/button whose accessible name contains 'csv'
    if not exported:
        try:
            links = page.get_by_role("link")
            if await links.count() > 0:
                total = await links.count()
                for i in range(total):
                    l = links.nth(i)
                    try:
                        name = (await l.inner_text()).strip()
                    except Exception:
                        name = ""
                    if name and 'csv' in name.lower():
                        await l.click()
                        exported = True
                        break
        except Exception:
            pass

    if not exported:
        try:
            buttons = page.get_by_role("button")
            if await buttons.count() > 0:
                total = await buttons.count()
                for i in range(total):
                    b = buttons.nth(i)
                    try:
                        name = (await b.inner_text()).strip()
                    except Exception:
                        name = ""
                    if name and 'csv' in name.lower():
                        await b.click()
                        exported = True
                        break
        except Exception:
            pass

    # Done: if export was clicked it was the final action; otherwise the report should now be generated in-page.
    return

